#!/usr/bin/env bash
# PR 本文に「検証証跡」が書かれているかを検査する。
#
# なぜ要るか: /ef:implement の検証ループ（レビュー・動作確認）は SKILL.md の文言でしか
# 拘束されておらず、実際に省略が起きた（#41）。「何を実行したか」を PR 本文に書かせ、
# **書かれていない PR を機械的に落とす**ことで、省略が報告に現れない状態をなくす。
#
# 判定はマーカー（下の MARKER）で行う。見出し名は縛らない —— 実際の PR は
# 実装 / release で見出しがまったく違い、テンプレも使われていないため（#46 の調査）。
#
# **このファイルが判定の正本で、bootstrap が利用者リポジトリへ配る実体そのもの**（#203）。
# 以前は `tests/check-pr-evidence.sh` にあり、**自リポの CI からしか呼ばれていなかった** ——
# 配布テンプレの CI に検査 step が無かったため、bootstrap した利用者リポジトリでは
# `docs-contract.md` の「CI が検査する」も implement/SKILL.md の「付け忘れると red になる」も
# 事実でなかった。**判定を 2 箇所に持たない**ため、テンプレ側を正本にして自リポが委譲する形にした。
#
# 配置:
#   - ef-devkit（正本）  plugins/ef/templates/_common/github/scripts/check-pr-evidence.sh
#                        ※ tests/check-pr-evidence.sh はここへ委譲する薄い wrapper
#   - 利用者リポジトリ    .github/scripts/check-pr-evidence.sh（bootstrap が配置）
#
# 使い方（パスは上の配置に読み替える）:
#   bash <このスクリプト> <本文ファイル>   # ファイルから読む
#   echo "$BODY" | bash <このスクリプト>   # 標準入力から読む
#
# 終了コード: 0=OK / 1=NG（理由を stderr に出す）
set -eu

MARKER='<!-- ef:verify-evidence -->'
MIN_LINES=3          # マーカー以降に要求する非空行の数（コマンド / 結果 / 未検証事項で最低 3 行）

if [ $# -ge 1 ]; then
  [ -r "$1" ] || { echo "ERROR: 読めません: $1" >&2; exit 1; }
  body=$(cat -- "$1")
else
  body=$(cat)        # 標準入力
fi

fail() {
  # **落とされた人が直せるメッセージを出す。** 直し方が分からないゲートは、
  # そのうち握り潰されるか、形だけ通されるようになる。
  cat >&2 <<EOF
FAIL: $1

PR 本文に検証証跡がありません。次のマーカーと、その下に実際にやったことを書いてください:

    $MARKER
    - review: git diff main...HEAD を実行。指摘 N 件（内容と対応）
    - verify: <実行したコマンド / 操作>。結果 <OK / NG>
    - 未検証: <確認できなかったこと と その理由>

要件:
  - マーカー行 $MARKER があること
  - マーカーより後ろに、空行・コメントを除いて $MIN_LINES 行以上の中身があること

検証できなかった場合も**その理由を書けば通ります**（「画面を持たないプロジェクトのため
chrome-devtools は非該当」など）。書けないなら、それは実行していないということです。
EOF
  exit 1
}

printf '%s\n' "$body" | grep -qF -- "$MARKER" || fail "マーカー $MARKER が見つかりません"

# マーカー直後から**次の見出し（## …）まで**を中身とみなして数える。
# 末尾まで数えると、マーカーを本文の先頭に置くだけで後続の全文がカウントされ、
# 検証を書かなくても通ってしまう（マーカーは検証を書く節の中に置く前提）。
# 空行・HTML コメント行・水平線・PR 定型行（Closes #N）は中身に数えない
# （マーカーだけ置いて通す、を防ぐ）。
#
# **「ラベルだけの行」の判定は、全角コロンを半角へ正規化してから行う**（#184）。
#   以前は `[^:：]` / `[:：]` と**ブラケットに非 ASCII を入れて**いたが、バイト指向の実装
#   （busybox grep 等）ではブラケット内の非 ASCII が**構成バイトに分解され「どれか 1 バイト」**に
#   なる。実測（busybox grep 1.37.0）では**中身のある行まで除外**され、証跡があるのに 0 行と
#   判定された —— 倒れる向きが**偽陽性**（通るべき PR が落ちる）なので害が大きい。
#   **`[...]` に非 ASCII を入れないのが一般則**（#181）。ただし `[^:：]` は**否定**ブラケットで
#   交替 `(:|：)` に書き換えられないため、**入力側を正規化して判定を ASCII だけで済ませる**。
#   `sed 's/：/:/g'` はブラケットを使わない単純な文字列置換なので、バイト指向でも安全に動く。
#   **行数は変わらない**ので、下の `wc -l` による件数カウントには影響しない
#   （この pipeline は行数しか使わず、置換後の中身は捨てられる）。
#
# **長さの上限（旧 `{0,20}`）も外した**（#184）。**繰り返し回数の数え方も実装で割れる** ——
#   GNU は**文字**単位、バイト指向の実装は**バイト**単位で数えるので、`- レビューと検証：`
#   （7 文字 = 21 バイト）が GNU では除外され busybox では残る、という食い違いが実測で出た。
#   上限そのものに意味は無く（短いラベルだけ落とすための安全弁だった）、**「コロンで終わり、
#   それ以外に内容が無い行はラベル」**という意図は上限なしでそのまま表せる。
#   結果として長いラベル行も落ちるが、**コロンで終わる行に中身は無い**ので意図どおり。
content=$(printf '%s\n' "$body" \
  | awk -v m="$MARKER" '
      index($0, m) { inblk=1; next }        # マーカー行の次から
      inblk && /^## /  { exit }             # 次の見出しで打ち切り
      inblk            { print }
    ' \
  | grep -vE '^\s*$' \
  | grep -vE '^\s*<!--' \
  | grep -vE '^\s*-{3,}\s*$' \
  | grep -vEi '^\s*(closes|fixes|resolves)\s+#[0-9]+\s*$' \
  | sed 's/：/:/g' \
  | grep -vE '^\s*[-*+]?\s*\**[^:]*\**\s*:\s*$' \
  | wc -l | tr -d ' ')

[ "${content:-0}" -ge "$MIN_LINES" ] \
  || fail "マーカーはありますが、その後の中身が ${content} 行しかありません（${MIN_LINES} 行以上必要）"

echo "OK: 検証証跡あり（マーカー以降 ${content} 行）"
